document.addEventListener("DOMContentLoaded", function () {
  var pinia = (0,pinia__WEBPACK_IMPORTED_MODULE_3__.createPinia)();
  (0,vue__WEBPACK_IMPORTED_MODULE_1__.createApp)(_vue_App_vue__WEBPACK_IMPORTED_MODULE_2__["default"]).use(pinia).mount("#app-calculator");
  var menuItems = document.querySelectorAll(".menu-item-has-children");
  if (window.innerWidth >= 768) {
    // Functionality for desktop devices
    menuItems.forEach(function (item) {
      var timer;
      item.addEventListener("mouseenter", function () {
        var subMenu = this.querySelector(".sub-menu");
        if (subMenu) {
          subMenu.style.display = "flex";
        }
      });
      item.addEventListener("mouseleave", function () {
        var subMenu = this.querySelector(".sub-menu");
        if (subMenu) {
          timer = setTimeout(function () {
            subMenu.style.display = "none";
          }, 300);
        }
      });
      item.addEventListener("mouseenter", function () {
        clearTimeout(timer);
      });
    });
  } else {
    // Functionality for mobile devices
    menuItems.forEach(function (item) {
      item.addEventListener("click", function () {
        var subMenu = this.querySelector(".sub-menu");
        if (subMenu) {
          if (subMenu.style.display === "none" || subMenu.style.display === "") {
            subMenu.style.display = "flex";
            subMenu.style.zIndex = 99999;
          } else {
            subMenu.style.display = "none";
          }
        }
      });
    });
  }
  var openBtn = document.querySelector(".btn-open");
  var closeBtn = document.querySelector(".btn-close");
  var menu = document.querySelector(".navigation");

  // Evento para el botón de cierre
  openBtn.addEventListener("click", function () {
    menu.style.display = "flex";
    closeBtn.style.display = "flex";
    openBtn.style.display = "none";
  });

  // Evento para el botón de apertura
  closeBtn.addEventListener("click", function () {
    menu.style.display = "none";
    closeBtn.style.display = "none";
    openBtn.style.display = "flex";
  });
  document.querySelectorAll(".submenu").forEach(function (menu) {
    menu.addEventListener("click", function () {
      menu.style.display = "flex";
    });
  });

  //   remove classname from header

  var header = document.querySelector(".contentHeader");
  if (header && window.location.pathname !== "/") {
    header.style.position = "relative";
    header.style.maxHeight = "unset";
    header.style.background = "white";
    header.classList.add("header-second");
  }
});

